with flattened_attrs as (select id, service, level, latency_ms, context, coalesce(context['version'], 'direct') as version_or_default, context['trace'] as trace, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, get_json_object(payload_json, '$.user.tier') as user_tier, array_contains(map_keys(context), 'version') as has_version from app_logs) select *, row_number() over (partition by level order by duration_sec, id) as event_seq, first_value(version_or_default, true) over (partition by level order by latency_ms, id rows between unbounded preceding and current row) as first_known_version_or_default from flattened_attrs;
